/**
 * Differential corpus for the PCRE->JS translator.
 *
 * tests/fixtures/regexp-corpus.json is generated by tools/regexp-corpus.php
 * against the reference implementation: every parse-phase pattern, run over
 * the fixture sources plus feature-specific snippets, with all matches and
 * byte-based capture offsets. This suite replays the corpus through
 * src/Regexp.js and asserts identical matches; byte offsets are converted
 * to UTF-16 code-unit indices (the port's offset model).
 */

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import * as Regexp from "../src/Regexp.js";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const corpus = JSON.parse(readFileSync(join(root, "tests", "fixtures", "regexp-corpus.json"), "utf8"));

/** Maps UTF-8 byte offsets in `s` to UTF-16 code-unit indices. */
function byteOffsetMap(s) {
  const bytes = Buffer.from(s, "utf8");
  const map = new Array(bytes.length + 1);
  let unit = 0;
  for (let i = 0; i < bytes.length; ) {
    const b = bytes[i];
    const width = b < 0x80 ? 1 : b < 0xe0 ? 2 : b < 0xf0 ? 3 : 4;
    for (let k = 0; k < width; k++) map[i + k] = unit;
    i += width;
    unit++;
  }
  map[bytes.length] = unit;
  return map;
}

describe("Regexp: differential corpus against the reference PCRE engine", () => {
  const maps = corpus.subjects.map(byteOffsetMap);

  /** @param {[string, number]} capture */
  const convert = (capture, map) => {
    const [text, offset] = capture;
    if (text === null) return null;
    return [text, map[offset]];
  };

  const check = (name, spec, subjects = null) => {
    it(`pattern ${name}`, () => {
      const { pattern, entries } = spec;

      for (const entry of entries) {
        const subject = (subjects ?? corpus.subjects)[entry.subjectIndex];
        const actual = Regexp.matchAll(subject, pattern).slice(0, 40);

        const expected = entry.matches;
        assert.equal(actual.length, expected.length, `match count for subject #${entry.subjectIndex}`);

        for (let mi = 0; mi < expected.length; mi++) {
          const map = subjects ? byteOffsetMap(subject) : maps[entry.subjectIndex];
          const expCaptures = expected[mi].map(c => convert(c, map));
          const act = actual[mi];
          assert.equal(
            act.matches.length,
            expCaptures.length,
            `group count in match ${mi} for subject #${entry.subjectIndex}`,
          );

          for (let g = 0; g < expCaptures.length; g++) {
            const [expText, expOffset] = expCaptures[g] ?? [null, null];
            assert.equal(act.matches[g], expText, `group ${g} text in match ${mi} for subject #${entry.subjectIndex}`);
            assert.equal(
              act.offsets[g],
              expOffset,
              `group ${g} offset in match ${mi} for subject #${entry.subjectIndex}`,
            );
          }
        }
      }
    });
  };

  for (const [name, spec] of Object.entries(corpus.patterns)) {
    check(name, spec);
  }

  corpus.pairs.forEach((spec, i) => {
    check(`extra-${i}`, spec, spec.subjects);
  });
});

describe("Regexp: unit behavior", () => {
  it("match finds first match at or after the offset", () => {
    const m = Regexp.match("one **x** two **y**", String.raw`~\*\*(.+?)\*\*~`);
    assert.equal(m.index, 4);
    assert.equal(m.matches[1], "x");

    const m2 = Regexp.match("one **x** two **y**", String.raw`~\*\*(.+?)\*\*~`, { offset: 14 });
    assert.equal(m2.index, 14);
    assert.equal(m2.matches[1], "y");
  });

  it("anchored patterns match only at the given offset (A flag)", () => {
    assert.equal(Regexp.match("aabc", String.raw`~ab~A`, { offset: 0 }), null); // sticky: match must start at the offset
    assert.ok(Regexp.match("xab", String.raw`~ab~A`, { offset: 1 }));
    assert.ok(Regexp.match("aaa bbb", String.raw`~b+~Am`, { offset: 4 }));
  });

  it("unmatched groups are null, not undefined", () => {
    const m = Regexp.match("ab", String.raw`~(a)(b)?(c)?~`);
    assert.equal(m.matches[1], "a");
    assert.equal(m.matches[2], "b");
    assert.equal(m.matches[3], null);
    assert.equal(m.offsets[3], null);
  });

  it("split captures delimiters with offsets", () => {
    const parts = Regexp.split("a\n\nb", String.raw`~(\n{2,})~`, { skipEmpty: true });
    assert.deepEqual(parts, [
      ["a", 0],
      ["\n\n", 1],
      ["b", 3],
    ]);
  });

  it("split honors the limit like preg_split", () => {
    assert.deepEqual(
      Regexp.split("a b c", String.raw`~\s+~`, { limit: 2 }).map(p => p[0]),
      ["a", "b c"],
    );
  });

  it("replace supports $1 references and callbacks", () => {
    assert.equal(Regexp.replace("a|b", String.raw`~(\|)~`, "<$1>"), "a<|>b");
    assert.equal(
      Regexp.replace("a|b", String.raw`~(\|)~`, m => m[1] + m[1]),
      "a||b",
    );
  });

  it("replace replaces ALL matches (preg_replace semantics)", () => {
    assert.equal(Regexp.replace("a|b|c", "~\\|~", "-"), "a-b-c");
  });

  it("possessive quantifiers do not backtrack", () => {
    // \S*+ eats everything; the final `*` required by the pattern cannot match
    assert.equal(Regexp.match("abc*", String.raw`~\S*+\*~`), null);
    assert.deepEqual(Regexp.match("abc*", String.raw`~\S*\*~`).matches, ["abc*"]);
  });

  it("atomic groups do not backtrack", () => {
    // (?>ab|a) commits to the longer alternative; the trailing b then fails
    assert.equal(Regexp.match("ab", String.raw`~(?>ab|a)b~`), null);
    assert.deepEqual(Regexp.match("axb", String.raw`~(?>ab|a)xb~`).matches, ["axb"]);
  });

  it("PCRE \\s matches Unicode spaces but not the BOM", () => {
    assert.deepEqual(Regexp.match("a\u00a0b", String.raw`~\s~`).matches, ["\u00a0"]);
    assert.equal(Regexp.match("a\ufeffb", String.raw`~\s~`), null);
    assert.deepEqual(Regexp.match("a\tb", String.raw`~\s~`).matches, ["\t"]);
  });

  it("quotes literals for extended mode", () => {
    assert.deepEqual(Regexp.match(":-))", "~" + Regexp.quote(":-)") + "+~").matches, [":-))"]);
  });

  it("recursion expands to a bounded depth", () => {
    // nested parens 4 deep, deeper than the failing innermost branch tolerance
    assert.deepEqual(Regexp.match("(((1)))", String.raw`~\((?: \d+ | \( (?0) \) )*\)(?!\d)~x`).matches, ["(((1)))"]);
  });
});

describe("compiled patterns are re-entrancy safe", () => {
  it("a replace callback matching the same pattern cannot corrupt the outer iteration", () => {
    const result = Regexp.replace("ab cd ef", "~[a-z]+~", matches => {
      const inner = Regexp.match("xy", "~[a-z]+~"); // nested, same pattern, mid-iteration
      return inner !== null ? matches[0].toUpperCase() : matches[0];
    });
    assert.strictEqual(result, "AB CD EF");
  });

  it("a nested replace with the same pattern cannot corrupt the outer iteration", () => {
    const result = Regexp.replace("a,b,c", "~,~", matches => {
      return Regexp.replace("x,y", "~,~", "-").length === 3 ? matches[0] : matches[0];
    });
    assert.strictEqual(result, "a,b,c");
  });

  it("a nested split with the same pattern cannot corrupt the outer replace", () => {
    const result = Regexp.replace("ab-cd", "~-~", () => {
      return Regexp.split("1-2-3", "~-~").length === 3 ? "-" : "?";
    });
    assert.strictEqual(result, "ab-cd");
  });
});

describe("PHP parity semantics", () => {
  it("replace: $0 is the whole match, $n falls back to the longest existing group, bogus references stay literal", () => {
    assert.strictEqual(Regexp.replace("abc", String.raw`~(\w)~`, "[$0]"), "[a][b][c]");
    // one capture group: $12 is group 1 followed by literal "2" (preg_replace)
    assert.strictEqual(Regexp.replace("abc", String.raw`~(\w)~`, "<$12>"), "<a2><b2><c2>");
    // two capture groups: $21 is group 2 followed by literal "1"
    assert.strictEqual(Regexp.replace("ab", String.raw`~(\w)(\w)~`, "<$21>"), "<b1>");
    // no valid group: the reference is left literal
    assert.strictEqual(Regexp.replace("abc", String.raw`~(\w)~`, "<$5>"), "<$5><$5><$5>");
  });

  it("splitPattern: the closing delimiter is the first unescaped one, and only implemented modifiers may follow", () => {
    // trailing garbage after the flags: PHP's "Unknown modifier"
    assert.throws(() => Regexp.splitPattern(String.raw`~abc~A~`), /Unknown modifier/);
    // PHP-valid but unimplemented modifier: rejected loudly, not silently ignored
    assert.throws(() => Regexp.splitPattern(String.raw`~abc~D`), /Unknown modifier/);
    // the delimiter must not be alphanumeric, backslash or whitespace
    assert.throws(() => Regexp.splitPattern("aabcda"), /Invalid pattern/);
    // escape at the end: unterminated
    assert.throws(() => Regexp.splitPattern(String.raw`~abc\~`), /Invalid pattern/);
    // and what PHP accepts
    assert.deepEqual(Regexp.splitPattern(String.raw`~abc~A`), ["abc", "A"]);
    assert.deepEqual(Regexp.splitPattern(String.raw`~a\~b~i`), ["a\\~b", "i"]);
  });

  it("split: never an empty list, no trailing empty piece, limit 0 is unlimited, skipEmpty drops null pieces", () => {
    // no match: the whole subject as the single piece
    assert.deepEqual(Regexp.split("abc", "~X~"), [["abc", 0]]);
    // empty subject: still one piece (preg_split never returns an empty list)
    assert.deepEqual(Regexp.split("", "~X~"), [["", 0]]);
    assert.deepEqual(Regexp.split("", "~X~", { skipEmpty: true }), []);
    // trailing delimiter: no final empty piece (documented divergence from PHP)
    assert.deepEqual(Regexp.split("a,", "~,~"), [["a", 0]]);
    // limit 0 means unlimited, like PHP
    assert.deepEqual(
      Regexp.split("a b c", "~ ~", { limit: 0 }).map(p => p[0]),
      ["a", "b", "c"],
    );
    // a captured group that did not participate: null piece, kept without skipEmpty
    assert.deepEqual(Regexp.split("aXb", String.raw`~(?:(\d)|X)~`), [
      ["a", 0],
      [null, null],
      ["b", 2],
    ]);
    assert.deepEqual(Regexp.split("aXb", String.raw`~(?:(\d)|X)~`, { skipEmpty: true }), [
      ["a", 0],
      ["b", 2],
    ]);
  });

  it("anchored patterns bind to the match offset; ^ still binds to the subject start", () => {
    // the A modifier: the match must start exactly at the given offset (PCRE)
    assert.deepEqual(Regexp.match("xxxabc", String.raw`~abc~A`, { offset: 3 }).matches, ["abc"]);
    assert.strictEqual(Regexp.match("xxxabc", String.raw`~abc~A`, { offset: 2 }), null);
    // ^ never matches at a nonzero offset, like preg_match with offset
    assert.strictEqual(Regexp.match("xxxabc", String.raw`~^abc~`, { offset: 3 }), null);
    assert.deepEqual(Regexp.match("abcxxx", String.raw`~^abc~`).matches, ["abc"]);
  });
});
